 69		Consider the pair $(\ell, u)$ sampled in the following way: first, sample the tuple $\bigl((u_0,s,0),(u,0,0)\bigr)$ from the CL distribution $\mu_{L_{\mathsf{ALine}}, L_{\mathsf{Point}}}$, and let $\ell = \ell(u_0, e_i)$ where $i = \chi(s)$. Then $u$ is a uniformly random point in $\F_q^m$, and $\ell$ is a line that goes through $u$ and is parallel to a uniformly random axis $i \in \{1,2,\ldots,m\}$.
 70	\end{lemma}
 71	\begin{proof}
 72		\uses{def:line-representative}
 73		Since $s$ is uniformly random in $\F_q$ and $m$ divides $q$, the index $i = \chi(s)$ is uniformly random in $\{1,2,\ldots,m\}$, so $(u_0,s)$ specifies a uniformly random axis-parallel line $\ell(u_0,e_i)$. Since $u_0 = L^{\mathrm{Ln}}_{e_i}(u)$ is the canonical representative of the line through $u$ in direction $e_i$, we have $u \in \ell(u_0,e_i)$.
 74	\end{proof}
